#[ignore = "requires NATIVE_SCALAR_TANGENT_ORACLE from the mounted native inspector test"]
fn native_sampler_accepts_the_real_clocked_ui_tangent_edit() {
    check_oracle("NATIVE_SCALAR_TANGENT_ORACLE", 0, "outgoing", 0.8, 1. / 3.);
}

