fn check_oracle(variable: &str, owner: usize, side: &str, x: f64, y: f64) {
    let path = std::env::var(variable).expect("UI oracle path required");
    let bytes = std::fs::read(path).unwrap();
    assert!(bytes.len() < 1024 * 1024, "UI oracle must stay bounded");
    let oracle: Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(oracle["schemaVersion"], 1);
    let composition: Composition = serde_json::from_value(oracle["composition"].clone()).unwrap();
    composition.validate_native_surface().unwrap();
    let restored: Composition = serde_json::from_slice(&serde_json::to_vec(&composition).unwrap()).unwrap();
    let CompositionTrack::Text { clips, .. } = &restored.tracks[0] else { panic!("UI text lane missing") };
    let AnimatableValue::Keyframes { track } = &clips[0].transform.x else { panic!("UI x curve missing") };
    assert_eq!(track.sample_clock.unwrap().parts(), (2, 1, 250000));
    let keys = serde_json::to_value(&track.keyframes).unwrap();
    assert!((keys[owner]["tangents"][side]["x"].as_f64().unwrap() - x).abs() < 1e-12);
    assert!((keys[owner]["tangents"][side]["y"].as_f64().unwrap() - y).abs() < 1e-12);
    assert_eq!(keys[owner]["tangents"][side]["mode"], "free");
    let samples = oracle["samples"].as_array().unwrap();
    assert_eq!(samples.len(), 8);
    for sample in samples {
        let local = sample["localUs"].as_u64().unwrap();
        let expected = sample["value"].as_f64().unwrap();
        let actual = AnimationSampleTime::Microseconds(local).sample_track(track).unwrap();
        assert!((actual - expected).abs() < 1e-11, "UI/native sample at {local}: {actual} != {expected}");
    }
    let mut missing_clock = track.clone();
    missing_clock.sample_clock = None;
    assert_ne!(AnimationSampleTime::Microseconds(250000).sample_track(&missing_clock).unwrap(), samples[4]["value"].as_f64().unwrap());
}


