async fn check_native_http_preview(variable: &str, channel: &str) {
    use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
    use tower::ServiceExt;
    use serde_json::json;
    let path=std::env::var(variable).unwrap();
    let oracle:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
    let mut base=oracle["composition"].clone();
    let track=base.pointer_mut(&format!("{channel}/track")).unwrap();
    track["interpolation"]=json!("linear");
    for key in track["keyframes"].as_array_mut().unwrap(){let key=key.as_object_mut().unwrap();key.remove("tangents");key.remove("interpolation");}
    let wrap=|content:Value|json!({"schemaVersion":1,"root":"root","compositions":{"root":{"content":content,"instances":[]}}});
    let base=wrap(base);
    let (state,_directory)=support::make_state(true,false).await;
    let owner=state.db.register_auth_user("scalar-preview-owner","public synthetic password").await.unwrap().unwrap();
    let saved=state.db.create_owned_composition_project("Saved scalar preview",&base,&[],&owner.user.username).await.unwrap();
    let context=json!({"projectId":saved.id,"expectedRevision":saved.revision});
    let app=support::router(state.clone());
    let request=|project:Value,token:&str|Request::builder().method("POST").uri("/api/compositions/nested-preview").header("content-type","application/json").header("authorization",format!("Bearer {token}")).body(Body::from(json!({"project":project,"compositionId":"root","timeUs":1250000,"renderedOutputs":{},"savedProject":context}).to_string())).unwrap();
    let draft=wrap(oracle["composition"].clone());
    let denied=app.clone().oneshot(request(draft.clone(),"invalid-session")).await.unwrap();
    assert_eq!(denied.status(),StatusCode::UNAUTHORIZED);
    let response=app.clone().oneshot(request(draft.clone(),&owner.token)).await.unwrap();
    let status=response.status();let actual=to_bytes(response.into_body(),1024*1024).await.unwrap();
    assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&actual));
    assert_eq!(actual.len(),64*48*4);
    let mut constant=draft;
    *constant.pointer_mut(&format!("/compositions/root/content{channel}")).unwrap()=json!({"mode":"constant","value":oracle["samples"][4]["value"]});
    let response=app.clone().oneshot(request(constant,&owner.token)).await.unwrap();
    assert_eq!(response.status(),StatusCode::OK);
    let expected=to_bytes(response.into_body(),1024*1024).await.unwrap();
    assert_eq!(actual,expected,"clocked UI draft must render at the browser's sampled position");
    let response=app.oneshot(request(base.clone(),&owner.token)).await.unwrap();
    assert_eq!(response.status(),StatusCode::OK);
    let unchanged=to_bytes(response.into_body(),1024*1024).await.unwrap();
    assert_ne!(actual,unchanged,"draft must visibly differ from the saved linear curve");
    let loaded=state.db.get_composition_project_for(&saved.id,&owner.user.username).await.unwrap().unwrap();
    assert_eq!(loaded.revision,saved.revision);assert_eq!(loaded.document,base);
}


#[test]
#[ignore = "requires the fresh mounted path progress trace"]
fn native_path_progress_matches_the_clocked_ui_samples() {
    use video_kadr_backend::domain::motion_path::PositionAnimation;
    let oracle:Value=serde_json::from_slice(&std::fs::read(std::env::var("NATIVE_PATH_PROGRESS_ORACLE").unwrap()).unwrap()).unwrap();
    let composition:Composition=serde_json::from_value(oracle["composition"].clone()).unwrap();
    composition.validate_native_surface().unwrap();
    let restored:Composition=serde_json::from_slice(&serde_json::to_vec(&composition).unwrap()).unwrap();
    let CompositionTrack::Text{clips,..}=&restored.tracks[0] else{panic!("Text lane required")};
    let position=clips[0].transform.position.as_ref().unwrap();
    let compiled=position.compile().unwrap();
    let samples=oracle["samples"].as_array().unwrap();assert_eq!(samples.len(),8);
    for sample in samples {
        let point=compiled.sample_at(AnimationSampleTime::Microseconds(sample["localUs"].as_u64().unwrap())).unwrap();
        let expected=5.+40.*sample["value"].as_f64().unwrap();
        assert!((point.x-expected).abs()<1e-9,"path UI/native {} != {expected}",point.x);assert_eq!(point.y,15.);
    }
    let PositionAnimation::Path{progress:AnimatableValue::Keyframes{track},..}=position else{panic!("Clocked progress required")};
    assert_eq!(track.sample_clock.unwrap().parts(),(2,1,250000));
}

#[test]
fn clocked_path_retains_integer_half_ticks_and_routes_video_to_native_rendering() {
    use video_kadr_backend::domain::{motion_path::PositionAnimation,flat_surface,group_surface::GroupSurface,composition::TransformSpec};
    use serde_json::json;
    let position:PositionAnimation=serde_json::from_value(json!({"mode":"path","path":{"nodes":[{"id":"a","point":{"x":0.,"y":0.},"inHandle":{"x":0.,"y":0.},"outHandle":{"x":0.,"y":0.},"segment":"line","tangentMode":"corner"},{"id":"b","point":{"x":1000.,"y":0.},"inHandle":{"x":0.,"y":0.},"outHandle":{"x":0.,"y":0.},"segment":"line","tangentMode":"corner"}]},"progress":{"mode":"keyframes","track":{"timeBase":1000,"sampleClock":{"rateNum":1,"rateDen":1,"offsetNum":-100000},"interpolation":"linear","keyframes":[{"tick":0,"value":0.},{"tick":1000,"value":1.}]}}})).unwrap();
    let compiled=position.compile().unwrap();
    let exact=compiled.sample_at(AnimationSampleTime::Microseconds(102500)).unwrap();
    assert_eq!(exact.x,3.);
    assert_eq!(compiled.sample_seconds(0.1025).unwrap().x,2.,"negative control must detect premature float rounding");
    let mut wire=serde_json::to_value(Composition::new(Default::default())).unwrap();wire["canvas"]["width"]=json!(64);wire["canvas"]["height"]=json!(48);
    wire["sources"]=json!({"source":{"id":"source","kind":"video","durationTicks":1000000,"width":16,"height":16,"hasAudio":false}});
    let mut transform=serde_json::to_value(TransformSpec::default()).unwrap();transform["position"]=serde_json::to_value(position).unwrap();
    wire["tracks"]=json!([{"kind":"video","id":"v","name":"Video","clips":[{"id":"clip","sourceId":"source","placement":{"timelineStartTick":0,"sourceInTick":0,"sourceOutTick":1000000,"speed":1.},"transform":transform,"opacity":{"mode":"constant","value":1.},"blendMode":"normal","sourceAudioEnabled":false}]}]);
    let clocked:Composition=serde_json::from_value(wire.clone()).unwrap();assert!(flat_surface::requires_native_video(&clocked));
    wire["tracks"][0]["clips"][0]["transform"]["position"]=json!({"mode":"xy","x":{"mode":"constant","value":3.},"y":{"mode":"constant","value":0.}});
    let expected:Composition=serde_json::from_value(wire).unwrap();
    let render=|composition:&Composition|{let mut decode=|_:&_,_:u64,_:bool|Ok(GroupSurface{width:16,height:16,rgba:[255,0,0,255].repeat(256)});flat_surface::render_media_layers(composition,102500,&mut||Ok(()),None,Some(&mut decode)).unwrap().unwrap()};
    assert_eq!(render(&clocked),render(&expected));
}


