async fn qualify_native_geometry(oracle_env: &str, spatial: bool) {
    use serde_json::json;
    use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
    use tower::ServiceExt;
    use video_kadr_backend::domain::motion_path::{MotionPath,PositionAnimation};
    let oracle:Value=serde_json::from_slice(&std::fs::read(std::env::var(oracle_env).unwrap()).unwrap()).unwrap();
    assert_eq!(oracle["schemaVersion"],1);
    let (state,_directory)=support::make_state(true,false).await;
    let owner=state.db.register_auth_user("path-geometry-owner","public synthetic password").await.unwrap().unwrap();
    let app=support::router(state.clone());
    let post=|endpoint:&str,body:Value|Request::builder().method("POST").uri(endpoint).header("content-type","application/json").header("authorization",format!("Bearer {}",owner.token)).body(Body::from(body.to_string())).unwrap();
    let response=app.clone().oneshot(post("/api/compositions/motion-path",oracle["request"].clone())).await.unwrap();
    let status=response.status();let bytes=to_bytes(response.into_body(),1024*1024).await.unwrap();assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&bytes));
    let solved:Value=serde_json::from_slice(&bytes).unwrap();
    let path:MotionPath=serde_json::from_value(solved["path"].clone()).unwrap();
    let composition:Composition=serde_json::from_value(oracle["composition"].clone()).unwrap();composition.validate_native_surface().unwrap();
    let CompositionTrack::Text{clips,..}=&composition.tracks[0]else{panic!("Text lane required")};
    let PositionAnimation::Path{path:accepted,progress:AnimatableValue::Keyframes{track}}=clips[0].transform.position.as_ref().unwrap()else{panic!("Clocked path required")};
    assert_eq!(&path,accepted);assert_eq!(path.nodes.len(),if spatial {2} else {3});
    if !spatial {assert_eq!(solved["length"],140.);}
    assert_eq!(track.sample_clock.unwrap().parts(),(2,1,250000));
    let point=clips[0].transform.position.as_ref().unwrap().compile().unwrap().sample_at(AnimationSampleTime::Microseconds(250000)).unwrap();let expected=if spatial {(4.,-3.)} else {(75.,15.)};assert_eq!((point.x,point.y),expected);
    let wrap=|content:Value|json!({"schemaVersion":1,"root":"root","compositions":{"root":{"content":content,"instances":[]}}});
    let draft=wrap(oracle["composition"].clone());let mut base=draft.clone();
    let nodes=&mut base["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["transform"]["position"]["path"]["nodes"];
    if spatial {nodes[0]["point"]=json!({"x":-10.,"y":-5.});} else {nodes.as_array_mut().unwrap().pop();}
    let saved=state.db.create_owned_composition_project("Geometry base",&base,&[],&owner.user.username).await.unwrap();
    let body=|project:Value|json!({"project":project,"compositionId":"root","timeUs":1250000,"renderedOutputs":{},"savedProject":{"projectId":saved.id,"expectedRevision":saved.revision}});
    let response=app.clone().oneshot(post("/api/compositions/nested-preview",body(draft.clone()))).await.unwrap();let status=response.status();let actual=to_bytes(response.into_body(),1024*1024).await.unwrap();assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&actual));
    let mut constant=draft;constant["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["transform"]["position"]=json!({"mode":"xy","x":{"mode":"constant","value":expected.0},"y":{"mode":"constant","value":expected.1}});
    let response=app.clone().oneshot(post("/api/compositions/nested-preview",body(constant))).await.unwrap();assert_eq!(response.status(),StatusCode::OK);assert_eq!(actual,to_bytes(response.into_body(),1024*1024).await.unwrap());
    let response=app.oneshot(post("/api/compositions/nested-preview",body(base.clone()))).await.unwrap();assert_eq!(response.status(),StatusCode::OK);assert_ne!(actual,to_bytes(response.into_body(),1024*1024).await.unwrap());
    let loaded=state.db.get_composition_project_for(&saved.id,&owner.user.username).await.unwrap().unwrap();assert_eq!(loaded.revision,saved.revision);assert_eq!(loaded.document,base);
}

