async fn qualify_native_timeline(oracle_env:&str,expected_opacity:f64,lane:usize,expected_x:f64) {
    use serde_json::json;
    use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
    use tower::ServiceExt;
    let bytes=std::fs::read(std::env::var(oracle_env).unwrap()).unwrap();assert!(bytes.len()<1024*1024);
    let oracle:Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(oracle["schemaVersion"],1);
    let composition:Composition=serde_json::from_value(oracle["after"].clone()).unwrap();composition.validate_native_surface().unwrap();
    let CompositionTrack::Text{clips,..}=&composition.tracks[lane]else{panic!("Text lane required")};
    let AnimatableValue::Keyframes{track}=&clips[0].transform.x else{panic!("Clocked X required")};
    if lane==0 {assert_eq!(track.sample_clock.unwrap().parts(),(2,1,250000));}else{assert!(track.sample_clock.is_none());}
    let local=AnimationSampleTime::Microseconds(oracle["timeUs"].as_u64().unwrap()-clips[0].timeline_start_tick);
    assert!((local.sample_track(track).unwrap()-expected_x).abs()<1e-9);
    let AnimatableValue::Keyframes{track:opacity}=&clips[0].opacity else{panic!("Opacity track required")};
    assert!((local.sample_track(opacity).unwrap()-expected_opacity).abs()<1e-9);
    let (state,_directory)=support::make_state(true,false).await;
    let owner=state.db.register_auth_user("timeline-keys-owner","public synthetic password").await.unwrap().unwrap();
    let app=support::router(state.clone());
    let wrap=|content:Value|json!({"schemaVersion":1,"root":"root","compositions":{"root":{"content":content,"instances":[]}}});
    let base=wrap(oracle["before"].clone());let draft=wrap(oracle["after"].clone());
    let saved=state.db.create_owned_composition_project("Timeline keys base",&base,&[],&owner.user.username).await.unwrap();
    let request=|project:Value|Request::builder().method("POST").uri("/api/compositions/nested-preview").header("content-type","application/json").header("authorization",format!("Bearer {}",owner.token)).body(Body::from(json!({"project":project,"compositionId":"root","timeUs":oracle["timeUs"],"renderedOutputs":{},"savedProject":{"projectId":saved.id,"expectedRevision":saved.revision}}).to_string())).unwrap();
    let response=app.clone().oneshot(request(draft.clone())).await.unwrap();let status=response.status();let actual=to_bytes(response.into_body(),1024*1024).await.unwrap();assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&actual));
    let mut constant=draft;
    constant["compositions"]["root"]["content"]["tracks"][lane]["clips"][0]["transform"]["x"]=json!({"mode":"constant","value":expected_x});
    constant["compositions"]["root"]["content"]["tracks"][lane]["clips"][0]["opacity"]=json!({"mode":"constant","value":expected_opacity});
    let response=app.clone().oneshot(request(constant)).await.unwrap();assert_eq!(response.status(),StatusCode::OK);assert_eq!(actual,to_bytes(response.into_body(),1024*1024).await.unwrap());
    let response=app.oneshot(request(base.clone())).await.unwrap();assert_eq!(response.status(),StatusCode::OK);assert_ne!(actual,to_bytes(response.into_body(),1024*1024).await.unwrap());
    let loaded=state.db.get_composition_project_for(&saved.id,&owner.user.username).await.unwrap().unwrap();assert_eq!(loaded.revision,saved.revision);assert_eq!(loaded.document,base);
}

